select count(*) from (select sbpo.ID, sbpo.PROCESS_ID, sbpo.EMPOWER_TYPE, sbpo.EMPOWER_AREA_CODE, sbpo.EMPOWER_AREA_NAME, sbpo.DEVICE_CODE, sbd.AN_DEVICE_NAME DEVICE_NAME, sbpo.DOCKING_DEPT_CODE, sbpo.DOCKING_DEPT_NAME, sbpo.ACROSS_EMPLOYEE_LOGIN, sbpo.ACROSS_EMPLOYEE_NAME, sbpo.TOP_SECRET_EMPLOYEE_LOGIN, sbpo.TOP_SECRET_EMPLOYEE_NAME, sbpo.APPLY_STATUS, sbpo.REFUSE_REASON, sbpo.APPLY_EMPLOYEE, sbpo.APPLY_ROLE, sbpo.APPLY_TIME, sbpo.PUBLIC_DEVICE_CODE, sbpo.PUBLIC_DEVICE_NAME, sbd.AN_FACTORY_CODE, sbd.AN_FACTORY_NAME, sbd.AN_BUILDING_CODE, sbd.AN_BUILDING,sbpo.build_sys_manager_role from safety_build_process_open sbpo left join safety_build_device sbd on sbpo.DEVICE_CODE = sbd.DEVICE_CODE where 1 = 1
