) TMP_T where 1 = 1

SELECT ID, PROCESS_ID, EMPOWER_TYPE, EMPOWER_AREA_CODE, EMPOWER_AREA_NAME, DEVICE_CODE, DEVICE_NAME, APPLY_STATUS, REFUSE_REASON, APPLY_EMPLOYEE, APPLY_ROLE, APPLY_TIME, AN_FACTORY_CODE, AN_FACTORY_NAME, AN_BUILDING_CODE, AN_BUILDING FROM (select sbpc.ID, sbpc.PROCESS_ID, sbpc.EMPOWER_TYPE, sbpc.EMPOWER_AREA_CODE, sbpc.EMPOWER_AREA_NAME, sbpc.DEVICE_CODE, sbpc.DEVICE_NAME, sbpc.APPLY_STATUS, sbpc.REFUSE_REASON, sbpc.APPLY_EMPLOYEE, sbpc.APPLY_ROLE, sbpc.APPLY_TIME, sbd.AN_FACTORY_CODE, sbd.AN_FACTORY_NAME, sbd.AN_BUILDING_CODE, sbd.AN_BUILDING from SAFETY.safety_build_process_close sbpc left join safety.safety_build_device sbd on sbpc.DEVICE_CODE = sbd.DEVICE_CODE where 1 = 1
and sbpc.PROCESS_ID = #{processId}
) TMP_T WHERE 1 = 1 ORDER BY ID ASC

SELECT ID, PROCESS_ID, EMPOWER_TYPE, EMPOWER_AREA_CODE, EMPOWER_AREA_NAME, DEVICE_CODE, DEVICE_NAME, APPLY_STATUS, REFUSE_REASON, APPLY_EMPLOYEE, APPLY_ROLE, APPLY_TIME, AN_FACTORY_CODE, AN_FACTORY_NAME, AN_BUILDING_CODE, AN_BUILDING FROM (select sbpc.ID, sbpc.PROCESS_ID, sbpc.EMPOWER_TYPE, sbpc.EMPOWER_AREA_CODE, sbpc.EMPOWER_AREA_NAME, sbpc.DEVICE_CODE, sbpc.DEVICE_NAME, sbpc.APPLY_STATUS, sbpc.REFUSE_REASON, sbpc.APPLY_EMPLOYEE, sbpc.APPLY_ROLE, sbpc.APPLY_TIME, sbd.AN_FACTORY_CODE, sbd.AN_FACTORY_NAME, sbd.AN_BUILDING_CODE, sbd.AN_BUILDING from SAFETY.safety_build_process_close sbpc left join safety.safety_build_device sbd on sbpc.DEVICE_CODE = sbd.DEVICE_CODE where 1 = 1 and sbpc.PROCESS_ID in
#{item}
) TMP_T WHERE 1 = 1 ORDER BY ID ASC
